 private int findTernaryOperator(String text, char operator) {
         int depth = 0;
         boolean inSingleQuote = false;
         boolean inDoubleQuote = false;

         for (int i = 0; i < text.length(); i++) {
             char c = text.charAt(i);

             if (!inSingleQuote && !inDoubleQuote) {
                 if (c == '$' && i + 1 < text.length() && text.charAt(i + 1) == '{') {
                     depth++;
                     i++; // skip the {
                     continue;
                 }
                 if (c == '}' && depth > 0) {
                     depth--;
                     continue;
                 }
                 if (c == '\'' && depth == 0) {
                     inSingleQuote = true;
                     continue;
                 }
                 if (c == '"' && depth == 0) {
                     inDoubleQuote = true;
                     continue;
                 }
-                if (c == operator && depth == 0) {
+                if (c == operator && depth == 0 && surroundedByWhitespace(text, i)) {
+                    // like the tokenizer, the operator must have whitespace around it,
+                    // so ${bean:svc?method=at(10:30)} is not a ternary
                     return i;
                 }
             } else if (inSingleQuote && c == '\'') {
                 inSingleQuote = false;
             } else if (inDoubleQuote && c == '"') {
                 inDoubleQuote = false;
             }
         }
         return -1;
     }

 private static String[] parseBeanRemainder(String remainder) {
         String ref = remainder;
         String method = null;
         String scope = null;

         if (remainder.contains("?method=") || remainder.contains("?scope=")) {
             ref = StringHelper.before(remainder, "?");
             String query = StringHelper.after(remainder, "?");
             try {
                 Map<String, Object> map = URISupport.parseQuery(query);
                 Object m = map.get("method");
                 Object s = map.get("scope");
                 method = m != null ? m.toString() : null;
                 scope = s != null ? s.toString() : null;
             } catch (URISyntaxException e) {
                 throw RuntimeCamelException.wrapRuntimeException(e);
             }
         } else {
             // first check :: because of my.own.Bean::method
             int doubleColonIndex = remainder.indexOf("::");
             // need to check that not inside params
             int beginOfParameterDeclaration = remainder.indexOf('(');
             if (doubleColonIndex > 0 && (!remainder.contains("(") || doubleColonIndex < beginOfParameterDeclaration)) {
                 ref = remainder.substring(0, doubleColonIndex);
                 method = remainder.substring(doubleColonIndex + 2);
+            } else if (remainder.startsWith("type:")) {
+                // type:com.foo.MyClass.myMethod: the class name has dots, so the method is the last part
+                // when it starts with a lower case letter, as Java method names do
+                String beforeParams = beginOfParameterDeclaration > 0
+                        ? remainder.substring(0, beginOfParameterDeclaration) : remainder;
+                int idx = beforeParams.lastIndexOf('.');
+                if (idx > 0 && idx + 1 < beforeParams.length()
+                        && Character.isLowerCase(beforeParams.charAt(idx + 1))) {
+                    ref = remainder.substring(0, idx);
+                    method = remainder.substring(idx + 1);
+                }
             } else {
                 int idx = remainder.indexOf('.');
                 if (idx > 0) {
                     ref = remainder.substring(0, idx);
                     method = remainder.substring(idx + 1);
                 }
             }
         }

         return new String[] { ref.trim(), method, scope };
     }

